\section{Introduction}

\subsection{Nahm sums and modularity}
Let $q$ be a formal variable (or $|q|<1$). For $m \in \N$ write the $q$-Pochhammer
symbol
\[
  (q;q)_m = \prod_{k=1}^{m}(1-q^k), \qquad (q;q)_0 = 1.
\]
Fix a rank $r \in \N$ and an integral quadratic form $Q : \Z^r \to \Z$. The
associated \emph{Nahm sum} is
\begin{equation}
  f_Q(q) = \sum_{n=(n_1,\dots,n_r)\in\N^r}
   \frac{q^{Q(n)}}{(q;q)_{n_1}(q;q)_{n_2}\cdots(q;q)_{n_r}}.
  \label{eq:nahm}
\end{equation}
The prototype is the first Rogers--Ramanujan identity ($r=1$, $Q(n)=n^2$):
\[
  \sum_{n\ge 0}\frac{q^{n^2}}{(q;q)_n}
   = \prod_{n\ge 0}\frac{1}{(1-q^{5n+1})(1-q^{5n+4})}.
\]
The right-hand side is \emph{modular}: an infinite product of $q$-Pochhammer
factors (an eta/theta quotient up to a rational power of $q$). Nahm's problem is to
classify the forms $Q$ for which $f_Q$ is modular. In rank one the modular cases are
well understood; in higher rank the classification is largely open.

\subsection{The discriminant condition}
Every quadratic form $Q$ in $r$ variables has a symmetric \emph{Hessian}
$H \in \Z^{r\times r}$ with
\begin{equation}
  Q(n) = \tfrac12\, n^\tr H\, n + (\text{lower order}).
  \label{eq:hessian}
\end{equation}
Define the \emph{discriminant} of the Nahm datum to be $\disc(H) = \det H$. The
object of study is the following.

\begin{conjecture}[Grand Conjecture, rank four]
$f_Q$ is modular $\iff \det H \in \{8,12,16\}$.
\end{conjecture}

This paper does \emph{not} prove the Grand Conjecture. Our contribution is to prove
that the discriminant is the structurally correct invariant on which such a criterion
must rest, and that the target set is realised by genuine positive forms: we make the
conjecture well posed (invariance), structured (multiplicativity), and non-vacuous
(realisability).

\section{Definitions}

\begin{definition}[Discriminant of a rank-four Nahm datum]
For a symmetric integer matrix $H \in \Z^{4\times 4}$ (the Hessian of the defining
quadratic form), the \emph{discriminant} is $\disc(H) := \det H \in \Z$. In the
formalization this is \texttt{disc H := H.det}.
\end{definition}

\begin{definition}[Unimodular change of variables]
An integer matrix $S \in \Z^{r\times r}$ is \emph{unimodular} if $\det S = \pm 1$;
equivalently $S$ is invertible over $\Z$. A unimodular substitution $n \mapsto Sn$
acts on Hessians by the congruence action $H \mapsto S^\tr H S$, the correct
transformation of \eqref{eq:hessian} under a linear change of variable.
\end{definition}

\begin{definition}[Orthogonal direct sum]
Given forms with Hessians $A \in \Z^{m\times m}$ and $D \in \Z^{n\times n}$, their
orthogonal direct sum has block-diagonal Hessian
\[
  A \oplus D = \begin{pmatrix} A & 0 \\ 0 & D \end{pmatrix} \in \Z^{(m+n)\times(m+n)},
\]
modelling the stacking of two non-interacting Nahm data, since
$f_{Q_A \oplus Q_D}(q) = f_{Q_A}(q)\,f_{Q_D}(q)$ at the level of defining sums.
\end{definition}

\section{Main results}

\subsection{The congruence transformation law}
\begin{theorem}[\texttt{det\_congr}]
Let $R$ be a commutative ring and $S,H \in R^{n\times n}$. Then
\[
  \det\!\big(S^\tr H S\big) = (\det S)^2\,\det H.
\]
\end{theorem}
\begin{proof}[Proof sketch]
Apply multiplicativity of the determinant twice:
$\det(S^\tr H S) = \det(S^\tr)\det(H)\det(S)$. Since $\det(S^\tr)=\det S$, this equals
$(\det S)(\det H)(\det S) = (\det S)^2\det H$. In Lean:
\texttt{rw [det\_mul, det\_mul, det\_transpose]; ring}.
\end{proof}

The law holds over an arbitrary commutative ring; integrality enters only in the next
step, where it forces the square factor to equal $1$.

\subsection{Strict unimodular invariance}
\begin{theorem}[\texttt{disc\_invariant}]
Let $S,H \in \Z^{4\times 4}$ with $\det S = 1$ or $\det S = -1$. Then
\[
  \disc\!\big(S^\tr H S\big) = \disc(H).
\]
\end{theorem}
\begin{proof}[Proof sketch]
Unfold $\disc=\det$ and apply Theorem~1: $\disc(S^\tr H S) = (\det S)^2\disc(H)$. In
either case $\det S = \pm 1$ gives $(\det S)^2 = 1$, so the factor disappears. In Lean:
\texttt{rw [det\_congr]; rcases hS with h | h <;> simp [h]}.
\end{proof}

\begin{remark}
Over $\Q$ or $\R$ the discriminant is invariant only modulo squares, because $\det S$
may be any nonzero scalar. Over $\Z$ the unimodularity constraint $\det S=\pm1$
upgrades this to strict equality, making $\det H$ a well-defined function on the
integral equivalence class $[H]$. Hence any coordinate-free modularity criterion can
depend on $H$ only through $\det H$.
\end{remark}

\subsection{Multiplicativity on direct sums}
\begin{theorem}[\texttt{disc\_directSum\_mul}]
For $A \in \Z^{m\times m}$ and $D \in \Z^{n\times n}$,
\[
  \det\begin{pmatrix} A & 0 \\ 0 & D \end{pmatrix} = \det A \cdot \det D.
\]
\end{theorem}
\begin{proof}[Proof sketch]
The determinant of a block-diagonal matrix (zero upper-right block) factors as the
product of the diagonal blocks' determinants. In Lean this is
\texttt{det\_fromBlocks\_zero}$_{12}$ \texttt{A 0 D}.
\end{proof}

\begin{theorem}[\texttt{disc\_diagonal}]
For $d : \{1,2,3,4\} \to \Z$,
\[
  \disc\big(\diag(d_1,d_2,d_3,d_4)\big) = \prod_{i=1}^{4} d_i.
\]
\end{theorem}
\begin{proof}[Proof sketch]
The determinant of a diagonal matrix is the product of its diagonal entries
(\texttt{det\_diagonal}).
\end{proof}

\begin{corollary}[Building-block calculus]
Iterating Theorem~3 expresses a diagonal rank-four datum as an orthogonal direct sum
of four rank-one data; by Theorem~4 its discriminant is the product of the four
rank-one discriminants. Since the smallest modular rank-one piece ($A_1$ type) has
discriminant $2$, the factorizations
\[
  8 = 2\cdot2\cdot2\cdot1,\quad 12 = 3\cdot2\cdot2\cdot1,\quad 16 = 2\cdot2\cdot2\cdot2
\]
predict the admissible block types: rank-one $A_1$ pieces (disc $2$), small
Cartan-type pieces (disc $3,4$), and trivial pieces (disc $1$).
\end{corollary}

\subsection{Realisability of the target set}
\begin{theorem}[\texttt{realizable}]
For each $d \in \{8,12,16\}$ there exists a symmetric integer Hessian
$H \in \Z^{4\times 4}$ with strictly positive diagonal ($H_{ii}>0$ for all $i$) and
$\disc(H)=d$.
\end{theorem}
\begin{proof}[Proof sketch]
Exhibit diagonal witnesses and compute via Theorem~4:
\[
  \diag(2,2,2,1)\mapsto 8,\quad \diag(2,2,3,1)\mapsto 12,\quad \diag(2,2,2,2)\mapsto 16.
\]
Each is symmetric (\texttt{isSymm\_diagonal}), has positive diagonal (checked
entrywise via \texttt{fin\_cases}), and its determinant is the product of the diagonal
entries (\texttt{det\_diagonal}, \texttt{Fin.prod\_univ\_four}).
\end{proof}

\begin{remark}
Positivity of the diagonal of a diagonal integer form already guarantees
positive-definiteness, so the witnesses are bona-fide non-degenerate Nahm data; the
Grand Conjecture is not vacuously true. Each witness contains two doubled coordinates
(repeated entry $2$), matching the conjectural prediction that $4 \mid \det H$ governs
modularity.
\end{remark}

\section{Algorithms}

\noindent\textbf{Algorithm A (Discriminant of a Nahm datum).} Given symmetric
$H \in \Z^{4\times 4}$, return $\det H$ by exact integer elimination; complexity
$O(r^3)$ ring operations. By Theorem~2 the output is a class function.

\noindent\textbf{Algorithm B (Discriminant-condition modularity oracle).} Compute
$d=\det H$; return \emph{candidate-modular} iff $d \in \{8,12,16\}$. By Theorem~5 it
accepts a nonempty set of genuine forms.

\noindent\textbf{Algorithm C (Unimodular-invariance certificate).} Given $H$ and a
unimodular $S$, verify $\det(S^\tr H S)=\det H$; guaranteed by Theorems~1--2.

\noindent\textbf{Algorithm D (Block-factorization search).} For a target
$d \in \{8,12,16\}$, enumerate factorizations $d=d_1d_2d_3d_4$ with $d_i \ge 1$; each
yields a diagonal witness with discriminant $d$ by Theorem~4.

\section{Applications and significance}
\begin{enumerate}
\item \textbf{A decidable surrogate.} Theorems~1--2 reduce a potential modularity test
  to a single exact $4\times4$ integer determinant, invariant under change of variable.
\item \textbf{A search heuristic.} Algorithm~D generates candidate forms with the magic
  discriminants to test for Rogers--Ramanujan-type product identities.
\item \textbf{Equivalence-class reduction.} As $\det H$ is a strict class invariant,
  searches may be run on class representatives, shrinking the search space.
\end{enumerate}

\section{Discussion and future work}
The biconditional remains open; our results show its ``only if'' direction is governed
entirely by a class invariant. We record the program's leading conjectures.

\begin{conjecture}[Invariance governs modularity]
Integrally equivalent Hessians ($H'=S^\tr H S$, $\det S=\pm1$) are simultaneously
modular or not, and modularity depends on $H$ only through $\det H$.
\end{conjecture}

\begin{conjecture}[Exact target set]
The modular rank-four discriminants are precisely
$\{d : 4 \mid d,\ 8 \le d \le 16\} = \{8,12,16\}$; the divisibility $4 \mid d$ (not mere
evenness) reflects two doubled coordinates of an even lattice.
\end{conjecture}

\begin{conjecture}[Direct-sum decomposability]
Every modular rank-four datum is integrally equivalent to an orthogonal direct sum of
lower-rank modular data whose discriminants multiply to one of $8,12,16$.
\end{conjecture}

\begin{conjecture}[Degree balance]
Modularity requires the numerator exponent $Q(n)=\tfrac12 n^\tr H n$ to asymptotically
balance the denominator degree growth $\sum_j n_j(n_j+1)/2$.
\end{conjecture}

\section{Conclusion}
We established the invariance, multiplicativity, and realisability backbone for the
rank-four Nahm-sum modularity conjecture. The discriminant $\det H$ is a strict
unimodular invariant (Theorems~1--2), multiplies on direct sums with a transparent
diagonal special case (Theorems~3--4), and takes each conjectured value $8,12,16$ on
explicit positive forms (Theorem~5). These results make the conjecture well posed and
non-vacuous and isolate the precise lattice-theoretic content of its open direction.

